events.command:
$ErrorActionPreference='Stop'
$runItem=Get-Item -LiteralPath 'C:\Users\22061\.codex\worktrees\96a3\FPGA_Competition\report\evidence\S2B-T06\ps_connection_debug_20261009_113002_r01'
$identity=Get-Content -LiteralPath (Join-Path $runItem.FullName 'hw_server_identity.json') -Raw -Encoding utf8 | ConvertFrom-Json
$native=Get-CimInstance Win32_Process -Filter ("ProcessId="+$identity.native.ProcessId)
$launcher=Get-CimInstance Win32_Process -Filter ("ProcessId="+$identity.launcher_pid)
if ($null -eq $native -or $native.ParentProcessId -ne $identity.native.ParentProcessId -or $native.ExecutablePath -cne $identity.native.ExecutablePath -or [string]$native.CreationDate.ToFileTimeUtc() -cne $identity.native.CreationTimeFileTimeUtc) { throw '本次native服务身份不符，拒绝结束' }
$launcherSaved=@($identity.ancestor_chain | Where-Object { $_.ProcessId -eq $identity.launcher_pid })
if ($launcherSaved.Count -ne 1 -or $null -eq $launcher -or $launcher.ExecutablePath -cne $launcherSaved[0].ExecutablePath -or [string]$launcher.CreationDate.ToFileTimeUtc() -cne $launcherSaved[0].CreationTimeFileTimeUtc -or $native.ParentProcessId -ne $launcher.ProcessId) { throw '本次launcher归属不符，拒绝结束' }
if ((Get-FileHash -LiteralPath $native.ExecutablePath -Algorithm SHA256).Hash.ToLowerInvariant() -cne $identity.native_sha256) { throw '服务可执行文件SHA变化' }
$nativeProcess=Get-Process -Id $native.ProcessId
$launcherProcess=Get-Process -Id $launcher.ProcessId
Stop-Process -Id $native.ProcessId -ErrorAction Stop
if (-not $nativeProcess.WaitForExit(10000)) { throw '本次native服务未退出' }
$launcherExited=$launcherProcess.WaitForExit(5000)
if (-not $launcherExited) {
    $remainingLauncher=Get-CimInstance Win32_Process -Filter ("ProcessId="+$identity.launcher_pid)
    if ($null -eq $remainingLauncher -or [string]$remainingLauncher.CreationDate.ToFileTimeUtc() -cne $launcherSaved[0].CreationTimeFileTimeUtc -or $remainingLauncher.ExecutablePath -cne $launcherSaved[0].ExecutablePath) { throw 'launcher再次核对失败' }
    Stop-Process -Id $identity.launcher_pid
    $launcherExited=$launcherProcess.WaitForExit(5000)
}
if (-not $launcherExited) { throw 'launcher未退出' }
$listeners=@(Get-NetTCPConnection -LocalPort 3121 -State Listen -ErrorAction SilentlyContinue | Select-Object LocalAddress,LocalPort,OwningProcess)
[pscustomobject]@{status='OWNED_SERVER_CLOSED';native_pid=$identity.native.ProcessId;launcher_pid=$identity.launcher_pid;native_exited=$nativeProcess.HasExited;launcher_exited=$launcherProcess.HasExited;remaining_listeners=$listeners;closed_at_utc8=[DateTimeOffset]::UtcNow.ToOffset([TimeSpan]::FromHours(8)).ToString('o');cpu_resume_execution='NOT_RUN'} | ConvertTo-Json -Depth 5
